<div class="d-flex justify-content-between"><h3 class="h6">Highlights</h3><button type="button" class="btn btn-sm btn-outline-success" data-repeater-add="highlight-rows" data-template="highlight-template">Add highlight</button></div><div id="highlight-rows" data-next-index="{{ $package?->highlights->count()??0 }}">@foreach($package?->highlights??[] as $i=>$item)<div class="row g-2 border rounded p-3 my-2" data-repeater-row><input type="hidden" name="highlights[{{ $i }}][id]" value="{{ $item->id }}"><div class="col-md-4"><input class="form-control" name="highlights[{{ $i }}][title]" value="{{ $item->title }}" placeholder="Title"></div><div class="col-md-3"><input class="form-control" type="file" name="highlights[{{ $i }}][image]"></div><div class="col-md-3"><input class="form-control" name="highlights[{{ $i }}][alt_text]" value="{{ $item->alt_text }}" placeholder="Alt text"></div><div class="col-md-1"><input class="form-control" type="number" name="highlights[{{ $i }}][display_order]" value="{{ $item->display_order }}"></div><div class="col-md-1"><label class="text-danger"><input type="checkbox" name="highlights[{{ $i }}][_remove]" value="1"> Remove</label></div></div>@endforeach</div><template id="highlight-template"><div class="row g-2 border rounded p-3 my-2" data-repeater-row><div class="col-md-4"><input class="form-control" name="highlights[__INDEX__][title]" placeholder="Title" required></div><div class="col-md-3"><input class="form-control" type="file" name="highlights[__INDEX__][image]"></div><div class="col-md-3"><input class="form-control" name="highlights[__INDEX__][alt_text]" placeholder="Alt text"></div><div class="col-md-1"><input class="form-control" type="number" name="highlights[__INDEX__][display_order]" value="0"></div><div class="col-md-1"><button class="btn btn-outline-danger" type="button" data-remove-new-row>×</button></div></div></template>
